namespace docking.widgets.tab;








using docking.widgets.label;
using docking.widgets.label;
using generic.theme;
using ghidra.util.layout;
using resources;

/**
 * Component for representing individual tabs within a {@link GTabPanel}.
 *
 * @param <T> the type of the tab values
 */
public class GTab<T> : JPanel {
	private static Border TAB_BORDER = new GTabBorder(false);
	private static Border SELECTED_TAB_BORDER = new GTabBorder(true);
	private static readonly string SELECTED_FONT_TABS_ID = "font.widget.tabs.selected";
	private static readonly string FONT_TABS_ID = "font.widget.tabs";
	private static Icon EMPTY16_ICON = Icons.EMPTY_ICON;
	private static Icon CLOSE_ICON = new GIcon("icon.widget.tabs.close");
	private static Icon HIGHLIGHT_CLOSE_ICON = new GIcon("icon.widget.tabs.close.highlight");

	//@formatter:off
	private static Color FG_COLOR_UNSELECTED = new GColor("color.fg.widget.tabs.unselected");
	private static Color FG_COLOR_SELECTED_INACTIVE = new GColor("color.fg.widget.tabs.selected.inactive");
	private static Color FG_COLOR_SELECTED_ACTIVE = new GColor("color.fg.widget.tabs.selected.active");
	
	private static Color BG_COLOR_HIGHLIGHTED = new GColor("color.bg.widget.tabs.highlighted");
	static Color BG_COLOR_UNSELECTED = new GColor("color.bg.widget.tabs.unselected");
	static Color BG_COLOR_SELECTED_INACTIVE = new GColor("color.bg.widget.tabs.selected.inactive");
	static Color BG_COLOR_SELECTED_ACTIVE = new GColor("color.bg.widget.tabs.selected.active");
	//@formatter:on

	private GTabPanel<T> tabPanel;
	private T value;
	private JLabel closeLabel;
	private JLabel nameLabel;
	private bool isSelected;

	GTab(GTabPanel<T> gTabPanel, T value, bool selected) : base(new HorizontalLayout(10))
    {
		this.tabPanel = gTabPanel;
		this.value = value;

		setBorder(selected ? SELECTED_TAB_BORDER : TAB_BORDER);

		nameLabel = new GDLabel();
		nameLabel.setName("Tab Label");
		nameLabel.setText(tabPanel.getDisplayName(value));
		nameLabel.setIcon(tabPanel.getValueIcon(value));
		nameLabel.setToolTipText(tabPanel.getValueToolTip(value));

		Gui.registerFont(nameLabel, selected ? SELECTED_FONT_TABS_ID : FONT_TABS_ID);
		add(nameLabel, BorderLayout.WEST);

		closeLabel = new GIconLabel(selected ? CLOSE_ICON : EMPTY16_ICON);
		closeLabel.setToolTipText("Close");
		closeLabel.setName("Close");
		closeLabel.setOpaque(true);
		add(closeLabel, BorderLayout.EAST);

		GTabMouseListener listener = new GTabMouseListener();
		installMouseListener(this, listener);
		initializeTabColors(false);
	}

	T getValue() {
		return value;
	}

	bool isSelected() {
		return isSelected;
	}

	void setSelected(bool selected) {
		this.isSelected = selected;
		initializeTabColors(false);
		setBorder(selected ? SELECTED_TAB_BORDER : TAB_BORDER);
	}

	void refresh() {
		nameLabel.setText(tabPanel.getDisplayName(value));
		nameLabel.setIcon(tabPanel.getValueIcon(value));
		nameLabel.setToolTipText(tabPanel.getValueToolTip(value));
		repaint();
	}

	void setHighlight(bool isHighlighted) {
		initializeTabColors(isHighlighted);
	}

	private void installMouseListener(Container c, GTabMouseListener listener) {

		c.addMouseListener(listener);
		c.addMouseMotionListener(listener);
		Component[] children = c.getComponents();
		foreach (Component element in children) {
			if (element is Container) {
				installMouseListener((Container) element, listener);
			}
			else {
				element.addMouseListener(listener);
				element.addMouseMotionListener(listener);
			}
		}
	}

	private void initializeTabColors(bool isHighlighted) {
		Color fg = getForegroundColor(isHighlighted);
		Color bg = getBackgroundColor(isHighlighted);
		setBackground(bg);
		nameLabel.setBackground(bg);
		nameLabel.setForeground(fg);
		closeLabel.setBackground(bg);
	}

	Color getBackgroundColor(bool isHighlighted) {
		if (isHighlighted) {
			return BG_COLOR_HIGHLIGHTED;
		}

		if (!isSelected) {
			return BG_COLOR_UNSELECTED;
		}

		bool isActive = tabPanel.isActive();
		return isActive ? BG_COLOR_SELECTED_ACTIVE : BG_COLOR_SELECTED_INACTIVE;
	}

	private Color getForegroundColor(bool isHighlighted) {
		if (isHighlighted) {
			return FG_COLOR_SELECTED_ACTIVE;
		}

		if (!isSelected) {
			return FG_COLOR_UNSELECTED;
		}

		bool isActive = tabPanel.isActive();
		return isActive ? FG_COLOR_SELECTED_ACTIVE : FG_COLOR_SELECTED_INACTIVE;
	}

	private class GTabMouseListener : MouseAdapter {
		/* @Override */
		public void mouseEntered(MouseEvent e) {
			closeLabel.setIcon(e.getSource() == closeLabel ? HIGHLIGHT_CLOSE_ICON : CLOSE_ICON);
		}

		/* @Override */
		public void mouseExited(MouseEvent e) {
			closeLabel.setIcon(isSelected ? CLOSE_ICON : EMPTY16_ICON);
		}

		/* @Override */
		public void mousePressed(MouseEvent e) {
			// close the list window if the user has clicked outside of the window
			if (!(e.getSource() is JList)) {
				tabPanel.closeTabList();
			}

			if (e.isPopupTrigger()) {
				return; // allow popup triggers to show actions without changing tabs
			}

			if (e.getSource() == closeLabel) {
				tabPanel.closeTab(value);
				return;
			}

			tabPanel.selectTab(value);
		}

		/* @Override */
		public void mouseReleased(MouseEvent e) {
			tabPanel.mouseReleased(this, e);
		}

		/* @Override */
		public void mouseDragged(MouseEvent e) {
			tabPanel.mouseDragged(this, e);
		}
	}

}
